void look_10(inout Look k) {

  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float grain = kn(uv * 600.0 + seed) * kfade(0.002);
