    c = mix(c, vec3(0.3, 0.29, 0.27), dirt * 0.55);
    k.colour = c * (1.0 - 0.55 * crack);
    k.rough = 0.93;
    k.height = 0.0006 * grit + 0.0008 * trowel + 0.0006 * pebble - 0.0008 * crack;

}














